#include <bits/stdc++.h>
using namespace std;

int main(void){

	string StoC="";
	for(int i=2;i<=9;i++){
		for(int j=0;j<3;j++)StoC+=(char)('0'+i); //3 characters for 2 3 4 5 6   8
		if((i==7)||(i==9))StoC+=(char)('0'+i);   //4 characters for           7   9
	}

	int n;
	string s,ans;

	cin>>n;
	for(int i=0;i<n;i++){
		cin>>s;
		ans+=StoC[s[0]-'a'];
	}
	cout<<ans<<endl;

	return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    int N;
    cin >> N;

    for (int i = 0; i < N; i++) {
        string Si;
        cin >> Si;

        int x = Si[0] - 'a';
        if ('s' - 'a' <= x) x -= 1;
        x = min(x / 3 + 2, 9);
        cout << x;
    }
    cout << endl;
}
